import itertools

n = 13
a = 6
b = 7

edges = []
for i in range(a):
    for j in range(a, n):
        edges.append((i, j))

# Verify triangle-free
is_triangle_free = True
for u, v, w in itertools.combinations(range(n), 3):
    if (u, v) in edges or (v, u) in edges:
        if (v, w) in edges or (w, v) in edges:
            if (u, w) in edges or (w, u) in edges:
                is_triangle_free = False
                break

# Verify maximal
is_maximal = True
for u, v in itertools.combinations(range(n), 2):
    if (u, v) not in edges and (v, u) not in edges:
        # Check if adding (u, v) creates a triangle
        creates_triangle = False
        for w in range(n):
            if w != u and w != v:
                if ((u, w) in edges or (w, u) in edges) and ((v, w) in edges or (w, v) in edges):
                    creates_triangle = True
                    break
        if not creates_triangle:
            is_maximal = False
            break

print(f"Triangle-free: {is_triangle_free}")
print(f"Maximal: {is_maximal}")
print(f"Edges: {edges}")
